import heapq
def dijk(g,s):
    d={n:float('inf')for n in g};d[s]=0
    pq=[(0,s)]
    while pq:
        dd,u=heapq.heappop(pq)
        if dd>d[u]:continue
        for v,w in g[u]:
            if d[u]+w<d[v]:
                d[v]=d[u]+w;heapq.heappush(pq,(d[v],v))
    return d

def change(coins,amt):
    coins.sort(reverse=True);r=[]
    for c in coins:
        while amt>=c: amt-=c;r.append(c)
    return r if amt==0 else None

def subsets(nums):
    r=[]
    def bt(s,c):
        r.append(c[:])
        for i in range(s,len(nums)):
            c.append(nums[i]);bt(i+1,c);c.pop()
    bt(0,[]);return r

