class UF:
    def __init__(s,n):s.p=list(range(n));s.r=[0]*n
    def find(s,x):
        if s.p[x]!=x:s.p[x]=s.find(s.p[x])
        return s.p[x]
    def union(s,x,y):
        rx,ry=s.find(x),s.find(y)
        if rx==ry:return False
        if s.r[rx]<s.r[ry]:rx,ry=ry,rx
        s.p[ry]=rx
        if s.r[rx]==s.r[ry]:s.r[rx]+=1
        return True

from collections import deque
def ts(g,ind):
    q=deque([n for n in g if ind[n]==0]);o=[]
    while q:
        n=q.popleft();o.append(n)
        for nb in g[n]:
            ind[nb]-=1
            if ind[nb]==0:q.append(nb)
    return o if len(o)==len(g) else []

