import functools
def retry(n=3):
    def dec(f):
        @functools.wraps(f)
        def w(*a,**k):
            for i in range(n):
                try:return f(*a,**k)
                except:
                    if i==n-1:raise
                    time.sleep(2**i)
        return w
    return dec

