Los memory leaks en JavaScript son más frecuentes de lo que parece y pueden degradar el rendimiento de una aplicación de forma silenciosa y progresiva. A diferencia de lenguajes con gestión manual de memoria, en JavaScript los leaks ocurren cuando el garbage collector no puede liberar objetos porque siguen siendo referenciados, aunque ya no sean necesarios.Event listeners sin eliminar El patrón más común de memory leak en el navegador: añadir listeners que nunca se eliminan, especialmente cuando el elemento DOM se recrea:// LEAK  cada vez que se monta el componente, añade otro listener
function montarComponente() {
  const boton = document.getElementById('enviar');
  boton.addEventListener('click', function handleClick() {
    console.log('click');
    // La función keepAlive mantiene viva la referencia al scope
    procesarDatos(cacheLocal);
  });
}

// Si montarComponente() se llama varias veces (SPA con navegación),
// el botón acumula N listeners sin que los anteriores se eliminen.

// CORRECTO  guardar referencia y eliminar al desmontar
function montarComponente() {
  const boton = document.getElementById('enviar');

  function handleClick() {
    console.log('click');
    procesarDatos(cacheLocal);
  }

  boton.addEventListener('click', handleClick);

  // Devolver función de limpieza
  return function desmontar() {
    boton.removeEventListener('click', handleClick);
  };
}

const desmontar = montarComponente();
// Al navegar a otra página:
desmontar();Closures que r

