            center: CLLocationCoordinate2D(latitude: 40.4168, longitude: -3.7038),
            span: MKCoordinateSpan(latitudeDelta: 0.05, longitudeDelta: 0.05)
        )
    )

    var body: some View {
        Map(position: $posicion)
            .ignoresSafeArea()
    }
} Otras opciones de posición:.camera(MapCamera(centerCoordinate:distance:heading:pitch:))para una cámara 3D,.automaticpara que MapKit decida y.userLocation(fallback:)para centrar en el usuario.Marker y Annotation: marcadores personalizados Markermuestra un pin estándar del sistema con un icono opcional.Annotationpermite una vista SwiftUI completamente personalizada:struct PuntoInteres: Identifiable {
